                                  "code": "import numpy as np\n\ndef train_pq_codebooks(vectors: np.ndarray, m: int, k_sub: int = 256):\n    n, d = vectors.shape\n    assert d % m == 0, \"Dimensi d harus habis dibagi m\"\n    d_sub = d // m\n    codebooks = np.zeros((m, k_sub, d_sub), dtype=np.float32)\n    \n    for j in range(m):\n        sub_vecs = vectors[:, j * d_sub : (j + 1) * d_sub]\n        # Inisialisasi sentroid acak dari sub-vektor\n        idx = np.random.choice(n, k_sub, replace=False)\n        codebooks[j] = sub_vecs[idx].copy()\n    return codebooks\n\ndef encode_pq(vectors: np.ndarray, codebooks: np.ndarray):\n    n, d = vectors.shape\n    m, k_sub, d_sub = codebooks.shape\n    codes = np.zeros((n, m), dtype=np.uint8)\n    \n    for j in range(m):\n        sub_vecs = vectors[:, j * d_sub : (j + 1) * d_sub]\n        cb = codebooks[j]\n        diff = sub_vecs[:, None, :] - cb[None, :, :]\n        dists = np.sum(diff ** 2, axis=-1)\n        codes[:, j] = np.argmin(dists, axis=1).astype(np.uint8)\n    return codes\n\nnp.random.seed(42)\ndata = np.random.randn(1000, 64).astype(np.float32)\nm_subspaces = 8 # 8 sub-ruang masing-masing berdimensi 8\nk_centroids = 256\n\ncbs = train_pq_codebooks(data, m=m_subspaces, k_sub=k_centroids)\npq_codes = encode_pq(data, cbs)\n\nprint(f\"Vektor Awal Dimensi d={data.shape[1]}: {data.nbytes} byte ({data[0].nbytes} byte/vektor)\")\nprint(f\"Hasil Encode PQ m={m_subspaces}: {pq_codes.nbytes} byte ({pq_codes[0].nbytes} byte/vektor)\")\nprint(f\"Faktor Kompresi Memori    : {data.nbytes / pq_codes.nbytes:.1f}x\")\nprint(f\"Sample Kode PQ Vektor #0   : {pq_codes[0].tolist()}\")",
