                                  "code": "import numpy as np\n\ndef compute_adc_table(query: np.ndarray, codebooks: np.ndarray):\n    m, k_sub, d_sub = codebooks.shape\n    lut = np.zeros((m, k_sub), dtype=np.float32)\n    for j in range(m):\n        q_sub = query[j * d_sub : (j + 1) * d_sub]\n        # Jarak kuadrat ke seluruh sentroid di sub-ruang j\n        diff = codebooks[j] - q_sub\n        lut[j] = np.sum(diff ** 2, axis=1)\n    return lut\n\ndef scan_adc_database(lut: np.ndarray, pq_codes: np.ndarray):\n    n, m = pq_codes.shape\n    # Agregasi jarak menggunakan indeks integer LUT\n    dists = np.zeros(n, dtype=np.float32)\n    for j in range(m):\n        dists += lut[j, pq_codes[:, j]]\n    return np.sqrt(dists)\n\nnp.random.seed(42)\nm, k_sub, d_sub = 4, 16, 4 # d = 16\ncbs = np.random.randn(m, k_sub, d_sub).astype(np.float32)\nn_vecs = 5\ncodes = np.random.randint(0, k_sub, size=(n_vecs, m), dtype=np.uint8)\nquery = np.random.randn(16).astype(np.float32)\n\nlut = compute_adc_table(query, cbs)\nadc_dists = scan_adc_database(lut, codes)\n\nprint(f\"Ukuran Lookup Table (m x k*): {lut.shape}\")\nprint(f\"Sampel Baris 0 LUT (Sub-ruang 1): {np.round(lut[0, :4], 3)}\")\nprint(f\"Jarak ADC Hasil Lookup ke 5 Vektor: {np.round(adc_dists, 4)}\")",
