                                  "code": "import numpy as np\n\n# Demonstrasi Kueri Multi-Tenant Menggunakan Filter Partition Key Terisolasi\nclass MultiTenantVectorEngine:\n    def __init__(self):\n        self.database = [] # List of tuples: (vec_id, tenant_id, vector)\n        \n    def insert(self, vec_id: int, tenant_id: str, vector: np.ndarray):\n        self.database.append((vec_id, tenant_id, vector))\n        \n    def search_isolated(self, tenant_id: str, query: np.ndarray, k: int = 2):\n        # Kueri HANYA mengevaluasi data milik tenant_id yang sah!\n        candidates = []\n        for vid, tid, v in self.database:\n            if tid == tenant_id:\n                dist = float(np.linalg.norm(v - query))\n                candidates.append((dist, vid))\n        candidates.sort()\n        return candidates[:k]\n\nnp.random.seed(42)\nengine = MultiTenantVectorEngine()\n# Masukkan data Tenant A dan Tenant B ke koleksi bersama\nengine.insert(1, \"tenant_A\", np.array([1.0, 0.0]))\nengine.insert(2, \"tenant_A\", np.array([0.9, 0.1]))\nengine.insert(3, \"tenant_B\", np.array([1.0, 0.0])) # Identik dengan #1 tapi milik B!\nengine.insert(4, \"tenant_B\", np.array([0.0, 1.0]))\n\nq = np.array([1.0, 0.0])\nres_a = engine.search_isolated(\"tenant_A\", q, k=2)\nres_b = engine.search_isolated(\"tenant_B\", q, k=2)\n\nprint(f\"Total Vektor di Koleksi Bersama: {len(engine.database)}\")\nprint(f\"Hasil Kueri Tenant A (Akses Sah): {[vid for _, vid in res_a]}\")\nprint(f\"Hasil Kueri Tenant B (Akses Sah): {[vid for _, vid in res_b]}\")\nprint(f\"Apakah Data Tenant B bocor ke Tenant A? {any(vid == 3 for _, vid in res_a)}\")",
